INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das IT-Sicherheitsgesetz nur für Kritische Infrastrukturen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Unternehmen sind betroffen"}, {"text": "Ja", "correct": false, "because": "Erweitert durch IT-SiG 2.0"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das IT-Sicherheitsgesetz?', 3, '[{"text": "Erhöhung der IT-Sicherheit", "correct": true, "because": "Schutz Kritischer Infrastrukturen"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Kosten senken", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt das IT-SiG an Kritische Infrastrukturen?', 5, '[{"text": "Stand der Technik", "correct": true, "because": "IT-Systeme absichern"}, {"text": "Meldepflicht", "correct": true, "because": "Vorfälle ans BSI melden"}, {"text": "Maximale Speicherung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IT-SiG 2.0 fordert Angriffserkennungssysteme. b) Es gilt nur für Energie.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle KRITIS-Sektoren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Umsetzung des IT-SiG?', 4, '[{"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Pflicht gemäß Gesetz"}, {"text": "Schwellenwerte", "correct": false, "because": "Bestimmen KRITIS-Status"}, {"text": "Farbschema", "correct": true, "because": "Nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das IT-SiG auch Gesundheit abdeckt?', 2, '[{"text": "Ja", "correct": true, "because": "KRITIS-Sektor Gesundheit enthalten"}, {"text": "Nein", "correct": false, "because": "Mehrere Sektoren betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflicht haben KRITIS-Betreiber laut IT-SiG?', 3, '[{"text": "Registrierung beim BSI", "correct": true, "because": "Pflicht seit IT-SiG 2.0"}, {"text": "Daten unbegrenzt speichern", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "UI optimieren", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sektoren fallen unter das IT-SiG?', 5, '[{"text": "Energie", "correct": true, "because": "KRITIS-Sektor"}, {"text": "Gesundheit", "correct": true, "because": "KRITIS-Sektor"}, {"text": "Design", "correct": false, "because": "Nicht sicherheitsrelevant"}, {"text": "Mode", "correct": false, "because": "Kein KRITIS-Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) IT-SiG schützt vor Cyberangriffen. b) Es gilt nur für Großunternehmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle KRITIS-Betreiber"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Einhaltung des IT-SiG?', 4, '[{"text": "Sicherheitsnachweis", "correct": false, "because": "Pflicht gegenüber BSI"}, {"text": "Angriffserkennung", "correct": false, "because": "Seit IT-SiG 2.0 erforderlich"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss jedes Unternehmen das IT-SiG beachten?', 2, '[{"text": "Nein", "correct": true, "because": "Nur KRITIS und bestimmte Firmen"}, {"text": "Ja", "correct": false, "because": "Zielgerichtet auf KRITIS"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fordert das IT-SiG von Energiebetreibern?', 4, '[{"text": "Stand der Technik", "correct": true, "because": "Pflicht für IT-Sicherheit"}, {"text": "Meldepflicht", "correct": true, "because": "Vorfälle ans BSI"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das IT-SiG nur technische Maßnahmen fordert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Maßnahmen"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich laut IT-SiG für Kritische Infrastrukturen?', 3, '[{"text": "Cyber-Sicherheit", "correct": true, "because": "Schutz vor Angriffen"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Sekundär"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IT-SiG gilt für Gesundheitssektor. b) Nachweis ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nachweis ist Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten gelten für KRITIS-Betreiber im IT-SiG?', 5, '[{"text": "Registrierung", "correct": true, "because": "Beim BSI erforderlich"}, {"text": "Systeme zur Angriffserkennung", "correct": true, "because": "Seit IT-SiG 2.0"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Umsetzung des IT-SiG unwichtig?', 3, '[{"text": "Meldepflicht", "correct": false, "because": "Pflicht bei Vorfällen"}, {"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Kern des Gesetzes"}, {"text": "Schriftarten", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit dem IT-SiG? Gilt es nur für Energie?', 3, '[{"text": "Nein", "correct": true, "because": "Umfasst mehrere Sektoren"}, {"text": "Ja", "correct": false, "because": "Auch Gesundheit etc."}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das IT-SiG Bußgelder vorsieht?', 2, '[{"text": "Ja", "correct": true, "because": "Bei Verstößen möglich"}, {"text": "Nein", "correct": false, "because": "Sanktionen enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das BSI im IT-SiG?', 4, '[{"text": "Überwachung", "correct": true, "because": "Prüft Nachweise"}, {"text": "Regulierung", "correct": true, "because": "Setzt Standards"}, {"text": "Datenverarbeitung", "correct": false, "because": "Nicht Aufgabe"}]');
